HISTORICAL_LIST_HASH = '4ecb70a791d56b7a909438f3cbf2f9d947ede27ae5e4c9e23a120ed830cce4c9'

def norm(text):
    return re.sub(r"\s+", " ", text).strip()

def main():
    records = {}
    for name, digest in VOICE_HASHES.items():
        path = BUILD / name
        assert hashlib.sha256(path.read_bytes()).hexdigest() == digest, name + " changed"
        for line in path.read_text().splitlines():
            if line.strip():
                row = json.loads(line)
                assert row["id"] not in records, row["id"]
                records[row["id"]] = row
    history = (BUILD / "synthesis/restricted-ids.md").read_text()
    tail = history.split("| id | why |", 1)[1]
    assert hashlib.sha256(tail.encode()).hexdigest() == HISTORICAL_LIST_HASH
    marked = set()
    for line in history.splitlines():
        if not line.startswith("|") or line.startswith(("| id", "|---")):
            continue
        cell = line.split("|")[1]
        for match in re.finditer(r"([a-z]{2,3}\d{1,2})-(\d{4})((?:\s*,\s*\d{4})*)", cell):
            marked.add(match[1] + "-" + match[2])
            marked.update(match[1] + "-" + extra for extra in re.findall(r"\d{4}", match[3]))
    assert len(marked) == 689 and marked <= records.keys()
    findings = (BUILD / "synthesis/findings.md").read_text()
    cited = set(re.findall(r"\[([a-z]+\d{1,2}-\d{4})\]", findings))
    assert ORIGINAL_CITED_IDS <= cited
    assert cited <= records.keys()
    blocks = re.findall(r"^> (.*?) `\[([a-z]+\d{1,2}-\d{4})\]`$", findings, re.M)
    complete = {i for quote, i in blocks if i in records and norm(quote) == norm(records[i]["quote"])}
    assert marked <= complete, sorted(marked - complete)
    assert "(restricted)" not in findings
    merged = [json.loads(line) for line in (BUILD / "voice-merged/all.jsonl").read_text().splitlines() if line.strip()]
    assert all(row.get("restricted") is False for row in merged)
    assert {row["id"] for row in merged if row.get("formerly_restricted")} == marked
    queue_path = BUILD / "scratchpad/unfilter-reread/queue.tsv"
    with queue_path.open(newline="") as stream:
        reader = csv.DictReader(stream, delimiter="\t")
        assert reader.fieldnames == ["kind", "id", "why_it_was_dropped"]
        queue = list(reader)
    counts = collections.Counter(row["id"] for row in queue)
    assert max(counts.values()) == 1
    assert all(row["kind"] in {"unit", "post"} and row["why_it_was_dropped"] and "-" in row["id"] and None not in row for row in queue)
    intake = set()
    for path in (BUILD / "_raw/reddit").glob("filter-*/safety-candidates.jsonl"):
        for line in path.read_text().splitlines():
            row = json.loads(line)
            intake.add(row["subreddit"] + "-" + row["id"])
    assert intake <= counts.keys()
    print(f"Original voice files unchanged: {len(VOICE_HASHES)} files, {len(records)} records")
    print(f"Original cited ids retained: {len(ORIGINAL_CITED_IDS)}; current cited ids resolve: {len(cited)}")
    print(f"Full formerly marked quotes match voice exactly (whitespace normalized): {len(marked)}/{len(marked)}")
    print("Historical list preserved; active merged restrictions: 0")
    print(f"Queue: {len(queue)} rows, 0 duplicate ids; safety intake covered: {len(intake)}/{len(intake)}")

if __name__ == "__main__":
    main()
